import { composeStack } from './src/services/stack/compose';

const WM = '';
const b64 = (s: string, m: string) => {
  const bin = atob(s); const a = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) a[i] = bin.charCodeAt(i);
  return new Blob([a], { type: m });
};
const bx = (c: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, f: string, r = 6) => {
  c.beginPath(); c.roundRect(x, y, w, h, r); c.fillStyle = f; c.fill();
};

/** 1000×1000 方图里的人形，全身居中——和主人素材一致。 */
function squareFigure(): HTMLCanvasElement {
  const c = document.createElement('canvas'); c.width = 1000; c.height = 1000;
  const x = c.getContext('2d')!;
  bx(x, 420, 720, 60, 220, '#3a4550', 8); bx(x, 520, 720, 60, 220, '#3a4550', 8);
  bx(x, 390, 380, 220, 360, '#46525e', 14);
  bx(x, 420, 430, 160, 120, '#5b6a78', 8);
  bx(x, 330, 400, 70, 230, '#3a4550', 12); bx(x, 600, 400, 70, 230, '#3a4550', 12);
  bx(x, 430, 200, 140, 170, '#4a5763', 12);
  bx(x, 450, 250, 100, 50, '#1d2b3a', 6);
  bx(x, 468, 265, 22, 14, '#ff8a3d', 3); bx(x, 510, 265, 22, 14, '#ff8a3d', 3);
  return c;
}
function vehicle(): HTMLCanvasElement {
  const c = document.createElement('canvas'); c.width = 1000; c.height = 1000;
  const x = c.getContext('2d')!;
  bx(x, 150, 520, 560, 180, '#3a4550', 14);
  bx(x, 700, 460, 200, 240, '#46525e', 12);
  for (const wx of [250, 420, 640]) {
    x.beginPath(); x.arc(wx, 720, 70, 0, Math.PI * 2); x.fillStyle = '#22262b'; x.fill();
  }
  return c;
}
function packaging(): HTMLCanvasElement {
  const c = document.createElement('canvas'); c.width = 1000; c.height = 1000;
  const x = c.getContext('2d')!;
  x.fillStyle = '#101418'; x.fillRect(120, 80, 760, 840);
  x.fillStyle = '#2b3440'; x.fillRect(170, 130, 660, 740);
  x.fillStyle = '#ff6b1a'; x.fillRect(200, 700, 600, 120);
  x.fillStyle = '#ffffff'; x.font = '900 90px Arial Black, sans-serif'; x.fillText('TRANS', 210, 240);
  return c;
}

const toBlob = (c: HTMLCanvasElement) => new Promise<Blob>((r, j) => c.toBlob((b) => (b ? r(b) : j(new Error('x'))), 'image/png'));

async function main(): Promise<void> {
  const out = await composeStack({
    slots: [
      { role: 'third', blob: await toBlob(packaging()) },
      { role: 'second', blob: await toBlob(vehicle()) },
      { role: 'hero', blob: await toBlob(squareFigure()) },
    ],
    watermark: b64(WM, 'image/png'),
    size: 800,
  });
  const img = document.createElement('img');
  img.src = URL.createObjectURL(out.blob);
  img.style.cssText = 'width:800px;display:block';
  document.body.innerHTML = ''; document.body.style.margin = '0';
  document.body.appendChild(img);
}
void main().catch((e: unknown) => { document.body.textContent = String(e); });
